package domain

import "time"

// TruthConsensus represents an AI-synthesized encyclopedia entry derived from
// a prediction market's real-time odds, volume, and verified sources of truth.
// This fulfills Illia Polosukhin's official hackathon benchmark concept:
// "AI encyclopedia with prediction markets: instead of community curation, every fact
// becomes a perpetual truth-seeking market. The official pages are generated by AI
// based on current market understanding."
type TruthConsensus struct {
	MarketID          string    `json:"marketId"`
	Title             string    `json:"title"`
	Category          string    `json:"category"`
	ProbabilityYes    float64   `json:"probabilityYes"`
	ProbabilityNo     float64   `json:"probabilityNo"`
	ConsensusVerdict  string    `json:"consensusVerdict"` // e.g. "LIKELY TRUE (84% Consensus)", "HIGHLY CONTESTED (51/49)", "UNLIKELY (12%)"
	ConfidenceLevel   string    `json:"confidenceLevel"`  // "HIGH", "MODERATE", "SPECULATIVE"
	VolumeUSD         float64   `json:"volumeUsd"`
	EncyclopediaEntry string    `json:"encyclopediaEntry"` // Comprehensive markdown synthesis of the current state of truth
	KeyFactors        []string  `json:"keyFactors"`        // Core evidence items and drivers
	SourcesOfTruth    []string  `json:"sourcesOfTruth"`
	ResolutionRule    string    `json:"resolutionRule"`
	LastSynthesizedAt time.Time `json:"lastSynthesizedAt"`
	Attribution       string    `json:"attribution"` // "Synthesized via Callit Truth-Seeking Engine (Augur/NEAR Thesis)"
}
